import { Accessor, createContext, createEffect, createMemo, useContext } from "solid-js";
import { createMutable, modifyMutable, reconcile } from "solid-js/store";

import LiveEventManager from "#core/ui/shell/live-event-logic/live-event-logic.js";
import { DatabaseCache } from "#core/ui/utilities/utilities-data.js";
import { AgeSelectModel } from "#core/ui-next/screens/create-game/age-select-model.js";
import { PlayerSetupParametersModel } from "#core/ui-next/screens/create-game/game-parameters-model.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";
import { FullTextSearch } from "#core/ui-next/utilities/search-utils.js";

export enum OwnershipAction {
	None,
	IncludedWith,
	LinkAccount,
}

export interface OwnershipData {
	action: OwnershipAction;
	reason: string;
}

export interface LeaderInfo {
	leaderID: string;
	name: string;
	rawName: string;
	icon: string;
	description: string;
	quote: string;
	abilityTextTag: string;
	abilityTitle: string;
	abilityText: string;
	ageUnlocks: string[];
	unlocks: string[];
	nextReward?: LegendPathReward;
	playCount: number;
	level: number;
	currentXp: number;
	nextLevelXp: number;
	prevLevelXp: number;
	tags: string[];
	isLocked: boolean;
	isOwned: boolean;
	ownershipData?: OwnershipData;
	sortIndex: number;
	fulltext: string;
	model: string;
	colors: HexColor | null;
	introText: string;
}

export interface LeaderSelectModel {
	leaders: LeaderInfo[];
	selectedLeader: Accessor<LeaderInfo>;
	setSelectedLeader: (leader: LeaderInfo) => void;
	// Returns matching leaderIds
	fulltextSearch: (text: string) => Set<string>;
}

function getOwnershipAction(actionName: string) {
	switch (actionName) {
		case "LOC_LOCKED_INCLUDED_WITH_CONTENT":
			return OwnershipAction.IncludedWith;

		case "LOC_LOCKED_LINK_ACCOUNT":
			return OwnershipAction.LinkAccount;
	}

	return OwnershipAction.None;
}

const leaderData_DatabaseCache = new DatabaseCache("config");

function createLeaderSelectModel(): LeaderSelectModel {
	const playerSetupModel = PlayerSetupParametersModel.get();
	const playerLeader = createMemo(() => playerSetupModel.players[GameContext.localPlayerID].PlayerLeader);
	const ageModel = AgeSelectModel.get();

	// TODO: This should be optimized to not update leader info if it already exists
	function getLeaders(): LeaderInfo[] {
		const leaders: LeaderInfo[] = [];

		if (playerLeader()) {
			// Additional queries
			const bonusItems = leaderData_DatabaseCache.query("select * from LeaderItems order by SortIndex");
			const tags = leaderData_DatabaseCache.query(
				"select * from LeaderTags inner join Tags on LeaderTags.TagType = Tags.TagType inner join TagCategories on Tags.TagCategoryType = TagCategories.TagCategoryType",
			);

			const unlocks = leaderData_DatabaseCache.query("select * from LeaderUnlocks order by SortIndex");
			// Commenting until table exists in database.
			const ownershipConditions = leaderData_DatabaseCache.query("select * from OwnershipConditions");
			const quotes = leaderData_DatabaseCache.query("select * from LeaderQuotes");
			const legendsPaths = Online.Metaprogression.getLegendPathsData();
			const victoryProgress = HallofFame.getLeaderProgress("RULESET_STANDARD");

			// If a domain parameter is invalid for the following reasons, include it.  Otherwise, skip over it.
			// This is so we can visualize some reasons (locked, ownership) but ignore others (invalid, age transition).
			const invalidReasonsToInclude = new Set([
				GameSetupDomainValueInvalidReason.Valid,
				GameSetupDomainValueInvalidReason.NotValidLocked,
				GameSetupDomainValueInvalidReason.NotValidOwnership,
			]);

			for (const leader of playerLeader().domain.possibleValues ?? []) {
				if (!invalidReasonsToInclude.has(leader.invalidReason)) {
					continue;
				}

				const leaderID = leader.value?.toString();
				const rawName = GameSetup.resolveString(leader.name);

				if (!leaderID || !rawName) {
					continue;
				}

				const leaderIntroText = leaderData_DatabaseCache.query(
					`select LeaderIntroText from Leaders where LeaderType = '${leaderID}'`,
				);
				const introText = leaderIntroText.length > 0 ? (leaderIntroText[0].LeaderIntroText as string) : "";

				const leaderHash = Database.makeHash(leaderID);
				const name = Locale.stylize(rawName ?? "");

				// check if leader live event is running, don't show random leader if so
				if (LiveEventManager.restrictToPreferredCivs() && leaderID == "RANDOM") {
					continue;
				}

				const colors = UI.Color.getDefaultColors3DAsHex(leaderHash);
				const domain = GameSetup.resolveString(leader.originDomain);
				const rawDescription = GameSetup.resolveString(leader.description) ?? "";
				const description = Locale.stylize(rawDescription);
				const leaderQuotes = quotes?.filter((q) => q.LeaderType == leaderID);
				const quote = leaderQuotes && leaderQuotes.length > 0 ? (leaderQuotes[0].Quote as string) : undefined;
				const valueBonusItems = bonusItems.filter(
					(item) => item.LeaderType == leaderID && item.LeaderDomain == domain,
				);

				const valueTags = tags
					.filter(
						(tag) =>
							!tag.HideInDetails &&
							(tag.LeaderType as string) == leaderID &&
							(tag.LeaderDomain as string) == domain,
					)
					.map((tag) => tag.Name as string);
				const valueUnlocks = unlocks.filter(
					(unlock) =>
						(unlock.LeaderType as string) == leaderID &&
						(unlock.LeaderDomain as string) == domain &&
						(!unlock.AgeDomain ||
							unlock.AgeDomain == ageModel.sortedAges.find((age) => unlock.AgeType == age.type)?.domain),
				);

				const rawAgeUnlocks: { name: string; age: string }[] = [];
				const rawUnlocks: string[] = [];

				for (const unlock of valueUnlocks) {
					const age = unlock.AgeDomain
						? ageModel.sortedAges.find((age) => unlock.AgeType == age.type)
						: undefined;
					if (age) {
						rawAgeUnlocks.push({ name: (unlock.Name as string) ?? "", age: age.name });
					} else {
						rawUnlocks.push((unlock.Name as string) ?? "");
					}
				}

				const formattedAgeUnlocks = rawAgeUnlocks.map((unlock) =>
					Locale.stylize("LOC_CREATE_GAME_UNLOCK_ITEM_IN_AGE", unlock.name as string, unlock.age),
				);

				const formattedUnlocks = rawUnlocks.map((unlock) =>
					Locale.stylize("LOC_CREATE_GAME_UNLOCK_ITEM", unlock as string),
				);

				const trait = valueBonusItems.find((item) => (item.Kind as string) == "KIND_TRAIT");
				const rawAbilityTitle = (trait?.Name as string | undefined) ?? "";
				const abilityTitle = Locale.stylize(rawAbilityTitle);
				const rawAbilityText = (trait?.Description as string | undefined) ?? "";
				const abilityText = Locale.stylize(rawAbilityText);
				const progress = victoryProgress.find((p: HallofFameLeaderProgress) => p.leaderType == leaderID);
				const playCount = progress ? (progress.playCount as number) : 0;
				let icon: string | null = GameSetup.resolveString(leader.icon);
				if (!icon) {
					console.error(`leader-select-panel: getLeaderData(): DB icon reference for leader ${name} is null`);
					icon = "fs://game/base-standard/leader_portrait_unknown.png"; // fallback
				}
				const legendData = legendsPaths.find(
					(item) => item.legendPathName == `${leaderID.replace("LEADER_", "LEGEND_PATH_")}`,
				);
				const currentLevel = legendData?.currentLevel ?? 0;
				const nextReward = legendData?.rewards?.find((reward) => reward.level > currentLevel);
				const isLocked = leader.invalidReason != GameSetupDomainValueInvalidReason.Valid;
				const isOwned = leader.invalidReason != GameSetupDomainValueInvalidReason.NotValidOwnership;
				let ownershipData: OwnershipData | undefined = undefined;

				if (!isOwned) {
					const ownershipEntry = ownershipConditions?.find((o) => o.ItemType == leaderID);
					if (ownershipEntry) {
						ownershipData = {
							reason: (ownershipEntry.Action as string) ?? "",
							action: getOwnershipAction(ownershipEntry.Action as string),
						};
					}
				}

				const fulltext = Locale.toLower(
					[
						name,
						Locale.plainText(rawDescription),
						Locale.plainText(rawAbilityTitle),
						Locale.plainText(rawAbilityText),
						...rawAgeUnlocks.map((u) => Locale.plainText(u.name)),
						...rawUnlocks.map((u) => Locale.plainText(u)),
						...valueTags.map((t) => Locale.plainText(t)),
					].join(" "),
				);

				const model = leaderID == "RANDOM" ? "LEADER_RANDOMIZED_GAME_ASSET" : `${leaderID}_GAME_ASSET`;

				leaders.push({
					leaderID: leaderID,
					name,
					rawName, // Required for composition as an argument
					icon: icon,
					description,
					abilityTextTag: (trait?.Description as string | undefined) ?? "",
					abilityTitle,
					abilityText,
					ageUnlocks: formattedAgeUnlocks,
					unlocks: formattedUnlocks,
					nextReward: nextReward,
					playCount: playCount,
					level: currentLevel,
					currentXp: Number(legendData?.currentXp ?? 0),
					nextLevelXp: Number(legendData?.nextLevelXp ?? 0),
					prevLevelXp: Number(legendData?.prevLevelXp ?? 0),
					tags: valueTags,
					isLocked: isLocked,
					isOwned: isOwned,
					ownershipData: ownershipData,
					sortIndex: leader.sortIndex,
					quote: quote ? Locale.stylize(quote) : "",
					fulltext,
					model,
					colors,
					introText,
				});
			}

			// Sort leader by leader name alphabetically
			leaders.sort((a, b) => a.name.localeCompare(b.name));

			// Then move the RANDOM leader to the front if it exists
			const randomLeaderIndex = leaders.findIndex((leader) => leader.leaderID == "RANDOM");
			if (randomLeaderIndex >= 0) {
				const [randomLeader] = leaders.splice(randomLeaderIndex, 1);
				leaders.unshift(randomLeader);
			}
		}

		return leaders;
	}

	const mutableLeaders = createMutable(getLeaders());

	const selectedLeader = createMemo(() => {
		const leaderId = playerLeader().value.value;
		return mutableLeaders.find((l) => l.leaderID == leaderId) ?? mutableLeaders[0];
	});

	function setSelectedLeader(leader: LeaderInfo) {
		playerLeader().setValue(leader.leaderID);
	}

	createEffect(() => {
		const updatedLeaders = getLeaders();
		modifyMutable(mutableLeaders, reconcile(updatedLeaders));
	});

	const search = new FullTextSearch("LeaderSelectFilter");
	// eslint-disable-next-line solid/reactivity
	search.addSearchData(mutableLeaders.map((l) => ({ key: l.leaderID, title: l.name, fullText: l.fulltext })));
	const fulltextSearch = (text: string) => search.find(text);

	return { leaders: mutableLeaders, selectedLeader, setSelectedLeader, fulltextSearch };
}

export const LeaderSelectModel = ModelRegistry.register(
	"LeaderSelectModel",
	ModelLifecycle.SharedInstance,
	createLeaderSelectModel,
);

export const LeaderSelectModelContext = createContext<LeaderSelectModel>();

export function useLeaderSelectModelContext() {
	const context = useContext(LeaderSelectModelContext);

	if (!context) {
		throw new Error("usLeaderSelectModel: Cannot find context!");
	}

	return context;
}
